package com.ryanjei.orushio.pve.map;import static org.junit.jupiter.api.Assertions.*;import java.nio.file.*;import java.util.*;import org.junit.jupiter.api.Test;import org.junit.jupiter.api.io.TempDir;
class SetupMarkerPersistenceTest{@TempDir Path temp;@Test void stableMarkerを保存再読込する(){YamlMapProfileRepository repository=new YamlMapProfileRepository(temp);MapProfile profile=MapProfileTest.complete("map-a");SetupMarker marker=new SetupMarker(UUID.randomUUID(),SetupMarkerType.FINAL_GATE,new BlockPoint(4,65,6,0,0),false);MapProfile value=new MapProfile(profile.mapId(),profile.displayName(),false,profile.templateDirectory(),profile.points(),profile.areas(),profile.createdAt(),profile.spawnMarkers(),List.of(marker));repository.save(value);assertEquals(marker,repository.find(profile.mapId()).orElseThrow().setupMarkers().getFirst());}@Test void 旧profileは空Markerとして後方互換読込()throws Exception{YamlMapProfileRepository repository=new YamlMapProfileRepository(temp);MapProfile profile=MapProfileTest.complete("map-a");repository.save(profile);Path file=temp.resolve("map-a/profile.yml");String yaml=Files.readString(file);Files.writeString(file,yaml.replace("setupMarkers: \"\"\n",""));assertTrue(repository.find(profile.mapId()).orElseThrow().setupMarkers().isEmpty());}}
